import json
with open("evidence/run-bare.jsonl") as f:
    for line in f:
        line = line.strip()
        if not line: continue
        try: obj = json.loads(line)
        except: continue
        t = obj.get("type", "?")
        if t == "system": 
            print(f"[system] {obj.get('subtype','')} tools={len(obj.get('tools',[]))}")
            continue
        if t == "assistant":
            msg = obj.get("message", {})
            for c in msg.get("content", []):
                if c.get("type") == "text":
                    print(f"[assistant/text] {c['text'][:400]}")
                elif c.get("type") == "tool_use":
                    print(f"[assistant/tool_use] {c['name']}({json.dumps(c.get('input',{}))[:200]})")
        elif t == "user":
            msg = obj.get("message", {})
            for c in msg.get("content", []):
                if c.get("type") == "tool_result":
                    text = c.get("content", "")
                    if isinstance(text, list):
                        text = " ".join(x.get("text","") for x in text if isinstance(x,dict))
